/**
 * Definition for Node.
 * struct Node { int val; Node* next; Node() : val(0), next(nullptr) {} Node(int x) : val(x), next(nullptr) {} };
 */
class Solution {
public:
    vector<Node*> splitCircularLinkedList(Node* head) {
        if (!head || head->next == head) return {head, head};
        Node* slow = head; Node* fast = head;
        while (fast->next != head && fast->next->next != head) {
            slow = slow->next;
            fast = fast->next->next;
        }
        if (fast->next != head) fast = fast->next;
        Node* second = slow->next;
        slow->next = head;
        fast->next = second;
        return {head, second};
    }
};

