class Solution {
public:
    vector<Node*> splitCircularLinkedList(Node* head) {
        int n = 1;
        Node* cur = head->next;
        while (cur != head) { n++; cur = cur->next; }
        int half = (n + 1) / 2;
        cur = head;
        for (int i = 0; i < half - 1; i++) cur = cur->next;
        Node* tail = head;
        for (int i = 0; i < n - 1; i++) tail = tail->next;
        Node* second = cur->next;
        cur->next = head;
        tail->next = second;
        return {head, second};
    }
};

